<template>
  <section class="signature-page">
    <header class="hero"><div><p class="eyebrow">STORY AGENT · STAGE 7 · SIGNED HUMAN REVIEW</p><h2>黄金卡真人审稿签名验证</h2><p>重验审稿材料，绑定卡片双哈希与风险角色，并用仓库侧信任策略验证外部 Ed25519 签名。</p></div><nav><RouterLink to="/story/stage7-golden-card-review">审稿接入</RouterLink><RouterLink to="/story/stage7-golden-card-expansion">候选补齐</RouterLink></nav></header>
    <div class="truth-lock"><strong>验签通过 ≠ 人工批准</strong><span>系统不创建签名、不落盘审稿、不修改卡片或索引，也不授予晋升和专业通过。</span></div>
    <p v-if="errorMessage" class="error-banner">{{ errorMessage }}</p>
    <section v-if="workspace" class="control-bar"><div><span>Trust policy</span><strong>{{ workspace.trust_policy.policy_id }}</strong></div><div><span>状态</span><strong>{{ workspace.trust_policy.status }}</strong></div><div><span>Trusted</span><strong>{{ workspace.trust_policy.trusted_signer_count }}</strong></div><label>候选卡<select v-model="selectedCardId"><option v-for="card in workspace.cards" :key="card.card_id" :value="card.card_id">{{ card.entry_name }} · {{ card.video_type }} · {{ card.risk_tier }}</option></select></label><button :disabled="loading" @click="loadWorkspace">生成绑定模板</button><button class="primary" :disabled="loading||!reviewText||!signatureText" @click="runInspection">{{ loading?'验签中…':'验证外部签名' }}</button></section>
    <section class="workspace-grid">
      <div class="editors">
        <article class="editor-card"><header><div><p class="eyebrow">REVIEW JSON</p><h3>三角色审稿材料</h3></div><span>只读重验</span></header><div class="toolbar"><label>导入审稿 JSON<input type="file" accept=".json,application/json" @change="importReview"></label></div><textarea v-model="reviewText" aria-label="Stage 7 golden card review JSON" spellcheck="false"/><footer>不落盘 · 不批准</footer></article>
        <article class="editor-card"><header><div><p class="eyebrow">SIGNATURE ATTESTATION</p><h3>外部签名记录</h3></div><span>仅内存</span></header><div class="toolbar"><label>导入签名 JSON<input type="file" accept=".json,application/json" @change="importSignature"></label><button @click="copySignature">复制模板</button><span>{{ copyMessage }}</span></div><textarea v-model="signatureText" aria-label="Stage 7 golden card review signature JSON" spellcheck="false"/><footer>不签名 · 不导入</footer></article>
      </div>
      <article class="result-card"><header><div><p class="eyebrow">VERIFICATION RESULT</p><h3>审稿、信任与密码学验证</h3></div><b :class="inspection?.signature_verification_ready?'ready':'blocked'">{{ inspection?.signature_verification_ready?'VERIFIED FOR EXTERNAL HANDOFF':'BLOCKED' }}</b></header>
        <div v-if="inspection" class="metrics"><div><span>审稿预检</span><strong>{{ inspection.checks.review_approval_preflight_reverified?'通过':'失败' }}</strong></div><div><span>签名</span><strong>{{ inspection.signature_summary.cryptographically_verified_signature_count }}/{{ inspection.signature_summary.required_role_count }}</strong></div><div><span>Trusted</span><strong>{{ inspection.signature_summary.trusted_signer_count }}</strong></div><div><span>人工批准</span><strong>0</strong></div></div>
        <div v-if="inspection" class="binding-panel"><span>Card <b>{{ inspection.expected_binding.card_id }}</b></span><span>片型 <b>{{ inspection.expected_binding.video_type }}</b></span><span>Review SHA <code>{{ shortHash(inspection.canonical_review_payload_sha256) }}</code></span><span>Attestation SHA <code>{{ shortHash(inspection.canonical_signature_payload_sha256) }}</code></span><span>Source SHA <code>{{ shortHash(inspection.expected_binding.source_card_file_sha256) }}</code></span><span>Card SHA <code>{{ shortHash(inspection.expected_binding.card_payload_sha256) }}</code></span></div>
        <section v-if="inspection" class="roles"><h4>风险角色签名</h4><div><span v-for="role in inspection.expected_binding.required_roles" :key="role">{{ roleLabel(role) }}</span></div></section>
        <section v-if="inspection" class="checks"><h4>签名门禁</h4><div><span v-for="(passed,key) in inspection.checks" :key="key" :class="passed?'ok':'fail'">{{ passed?'✓':'×' }} {{ checkLabel(key) }}</span></div></section>
        <section v-if="inspection?.issues.length" class="issues"><h4>问题 {{ inspection.issues.length }} 项</h4><article v-for="(item,index) in inspection.issues" :key="`${item.code}-${index}`"><header><b>{{ item.gate.toUpperCase() }}</b><code>{{ item.code }}</code></header><span>{{ item.path||'root' }}</span><p>{{ item.message }}</p></article></section>
        <div class="safety-grid"><span>Signature created <b>否</b></span><span>Signed review persisted <b>否</b></span><span>Source card modified <b>否</b></span><span>Index modified <b>否</b></span><span>Human approval granted <b>否</b></span><span>Golden card promoted <b>否</b></span><span>Professional passed <b>否</b></span></div>
      </article>
    </section>
  </section>
</template>

<script setup lang="ts">
import { onMounted,ref } from 'vue'
import type { Stage7GoldenCardReviewerRole,Stage7GoldenCardReviewSignatureInspectionResult,Stage7GoldenCardReviewSignatureWorkspace } from '@shared/types'
import { getStage7GoldenCardReviewSignatureWorkspace,inspectStage7GoldenCardReviewSignature } from '../api/stage7-golden-cards'
const workspace=ref<Stage7GoldenCardReviewSignatureWorkspace|null>(null),inspection=ref<Stage7GoldenCardReviewSignatureInspectionResult|null>(null),selectedCardId=ref(''),reviewText=ref(''),signatureText=ref(''),loading=ref(false),errorMessage=ref(''),copyMessage=ref('')
const labels:Record<string,string>={request_valid:'检查请求',signature_json_valid:'签名 JSON',signature_attestation_schema_valid:'Attestation schema',trust_policy_schema_valid:'Trust policy schema',trust_policy_active:'Trust policy 已激活',review_approval_preflight_reverified:'审稿预检重验',card_id_binding_valid:'Card ID 绑定',video_type_binding_valid:'片型绑定',source_file_digest_binding_valid:'源文件 SHA 绑定',card_payload_digest_binding_valid:'卡片 SHA 绑定',review_payload_digest_binding_valid:'审稿 Payload SHA',approval_decision_valid:'批准决定完整',required_roles_signed:'风险角色签名齐全',trusted_signer_bindings_valid:'Signer 信任绑定',signed_payload_digests_valid:'签名 Payload SHA',cryptographic_signatures_valid:'Ed25519 验签',signature_timestamps_valid:'签名时间',source_claimed_credit_rejected:'自报信用已拒绝'}
const roles:Record<Stage7GoldenCardReviewerRole,string>={source_reviewer:'来源审稿',authorization_reviewer:'授权审稿',type_director:'片型导演',fact_reviewer:'事实审稿',ethics_reviewer:'伦理审稿',local_culture_reviewer:'地方文化审稿'}
onMounted(loadWorkspace)
async function loadWorkspace(){loading.value=true;errorMessage.value='';const response=await getStage7GoldenCardReviewSignatureWorkspace(selectedCardId.value);loading.value=false;if(!response.ok||!response.data){errorMessage.value=response.error?.message??'签名工作区加载失败';return}workspace.value=response.data;selectedCardId.value=response.data.selected_card_id;reviewText.value=response.data.review_template_raw_json;signatureText.value=response.data.signature_template_raw_json;inspection.value=response.data.template_inspection}
async function runInspection(){loading.value=true;errorMessage.value='';const response=await inspectStage7GoldenCardReviewSignature({expected_card_id:selectedCardId.value,review_raw_json:reviewText.value,signature_raw_json:signatureText.value});loading.value=false;if(!response.ok||!response.data){errorMessage.value=response.error?.message??'黄金卡审稿签名验证失败';return}inspection.value=response.data}
async function importText(event:Event,target:{value:string}){const input=event.target as HTMLInputElement,file=input.files?.[0];if(!file)return;try{target.value=await file.text();errorMessage.value=''}catch(error){errorMessage.value=`导入失败：${(error as Error).message}`}finally{input.value=''}} function importReview(event:Event){return importText(event,reviewText)} function importSignature(event:Event){return importText(event,signatureText)}
async function copySignature(){try{await navigator.clipboard.writeText(signatureText.value);copyMessage.value='已复制'}catch{copyMessage.value='复制未授权'}window.setTimeout(()=>copyMessage.value='',1600)} function checkLabel(key:string){return labels[key]??key} function roleLabel(role:Stage7GoldenCardReviewerRole){return roles[role]} function shortHash(value:string){return value?`${value.slice(0,10)}…${value.slice(-6)}`:'—'}
</script>

