;align-items:center;justify-content:space-between;border-bottom:1px solid #413550}.editor-card h3,.result-card h3{margin:3px 0 0;font-size:15px}.editor-card header span{color:#8f82a0;font:9px ui-monospace,monospace}.result-card header>b{font-size:9px;letter-spacing:.07em}.ready{color:#7bd9bd}.blocked{color:#ff9bad}.toolbar{min-height:38px;padding:8px 10px;display:flex;align-items:center;gap:6px}.toolbar span{color:#9386a4;font-size:9px}.toolbar input{display:none}textarea{width:100%;min-height:650px;padding:13px;box-sizing:border-box;resize:vertical;border:0;border-block:1px solid #372c45;outline:0;color:#ded7e8;background:#08060c;font:9px/1.5 ui-monospace,SFMono-Regular,Menlo,monospace}.editor-card footer{padding:9px;color:#978aa8;font-size:9px}.metrics{margin:14px;display:grid;grid-template-columns:repeat(4,1fr);gap:6px}.metrics div{padding:9px;border-radius:7px;background:#30273d}.metrics span{display:block;color:#978ba6;font-size:8px}.metrics strong{font-size:14px}.metrics div:last-child strong{color:#ff9aac}.binding-panel,.safety-grid{margin:0 14px 12px;display:grid;grid-template-columns:repeat(2,1fr);gap:6px}.binding-panel span,.safety-grid span{padding:8px;border-radius:7px;color:#9589a4;background:#2a2235;font-size:8px}.binding-panel b,.binding-panel code,.safety-grid b{float:right;max-width:65%;color:#ded6e8;overflow-wrap:anywhere}.safety-grid b{color:#ff9bab}.roles,.checks,.issues{margin:0 14px 13px}.roles h4,.checks h4,.issues h4{margin:0 0 7px}.roles>div{display:flex;gap:5px}.roles span{padding:6px;border-radius:6px;color:#ceb9e9;background:#3a2c4b;font-size:8px}.checks>div{display:grid;grid-template-columns:repeat(2,1fr);gap:5px}.checks span{padding:7px;border-radius:6px;font-size:8px}.ok{color:#77d3ba;background:#14372f}.fail{color:#ed96a7;background:#3a1c28}.issues>article{margin:5px 0;padding:8px;border:1px solid #513642;border-radius:7px;background:#281820}.issues article header{display:flex;gap:7px}.issues article b{color:#e994a6;font-size:8px}.issues code{color:#c2aeb5;font-size:8px}.issues article>span{display:block;margin-top:3px;color:#927e85;font-size:8px}.issues p{margin:2px 0 0;color:#baa8ae;font-size:9px}
@media(max-width:1300px){.workspace-grid{grid-template-columns:1fr}.editors{position:static}textarea{min-height:450px}}@media(max-width:800px){.signature-page{padding:18px 12px}.hero,.truth-lock,.control-bar{align-items:flex-start;flex-direction:column}.control-bar label{width:100%}.editors{grid-template-columns:1fr}.metrics,.binding-panel,.safety-grid,.checks>div{grid-template-columns:1fr}}
